from pathlib import Path
import os,stat,json,subprocess
units=[
 ('fadego-staging','/srv/fadego-staging','/srv/projects/fadego',3),
 ('lowcost-europa','/srv/lowcost-europa','/srv/projects/lowcost-europa',2),
 ('pink-iptv-backend','/srv/pink-iptv','/srv/projects/pink-iptv',2),
]
def cmd(a,t=18):
 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def show(name):
 r=cmd(['systemctl','show',name+'.service','--no-pager','-p','ActiveState','-p','MainPID','-p','WorkingDirectory','-p','ExecStart'],13)
 if r.returncode:raise RuntimeError('Cannot inspect '+name)
 return dict(x.split('=',1) for x in r.stdout.splitlines() if '=' in x)
def bots():
 r=cmd(['pm2','jlist'],15)
 if r.returncode:raise RuntimeError('PM2 offline')
 return {x.get('name'):{'status':(x.get('pm2_env') or {}).get('status'),'pid':x.get('pid')} for x in json.loads(r.stdout) if x.get('name') in ('iptvpn_bot','telegram-robot-leads')}
state0={name:show(name) for name,_,_,_ in units}
if any(v.get('ActiveState')!='active' or not v.get('MainPID','0').isdigit() or int(v.get('MainPID','0'))<2 for v in state0.values()):raise RuntimeError('Service baseline not healthy')
pm0=bots()
if any(pm0.get(n,{}).get('status')!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot offline preflight')
source={}
meta={}
for name,old,new,count in units:
 p=Path('/etc/systemd/system')/(name+'.service')
 if not p.is_file() or p.is_symlink() or p.stat().st_uid!=0:raise RuntimeError('Unexpected unit file')
 b=p.read_bytes()
 if b.count(old.encode())!=count:raise RuntimeError('Old path references count differs: '+name)
 if state0[name].get('WorkingDirectory') is None or old not in state0[name]['WorkingDirectory']:raise RuntimeError('Active unit not using expected old path')
 if not Path(old).is_symlink() or Path(old).resolve()!=Path(new) or not Path(new).is_dir():raise RuntimeError('Compatibility symlink invalid for '+name)
 source[p]=b
 meta[p]=(p.stat().st_mode & 0o777,p.stat().st_uid,p.stat().st_gid)
 if name=='fadego-staging' and not (Path(new)/'current/node_modules/next/dist/bin/next').is_file():raise RuntimeError('FADEGO target binary missing')
 if name=='lowcost-europa' and cmd([new+'/.venv/bin/gunicorn','--version'],15).returncode:raise RuntimeError('LowCost target gunicorn not executable')
 if name=='pink-iptv-backend' and cmd([new+'/backend/.venv/bin/uvicorn','--version'],15).returncode:raise RuntimeError('PINK target uvicorn not executable')
updated=[]
try:
 for name,old,new,count in units:
  p=Path('/etc/systemd/system')/(name+'.service')
  dest=p.with_name(p.name+'.canonical-migration-tmp')
  if dest.exists() or dest.is_symlink():raise RuntimeError('Unexpected temporary unit present')
  b=source[p].replace(old.encode(),new.encode())
  with dest.open('xb') as f:
   f.write(b)
   f.flush()
   os.fsync(f.fileno())
  mode,uid,gid=meta[p]
  os.chmod(dest,mode)
  os.chown(dest,uid,gid)
  os.replace(dest,p)
  updated.append(p)
  if old.encode() in p.read_bytes():raise RuntimeError('Stale old path in modified unit')
 for p in updated:
  v=cmd(['systemd-analyze','verify',str(p)],25)
  if v.returncode:
   print('UNIT_VERIFY_FAILURE',p.name,'DETAIL',v.stderr[:280])
   raise RuntimeError('Systemd static unit validation failed')
 reload=cmd(['systemctl','daemon-reload'],30)
 if reload.returncode:raise RuntimeError('systemctl daemon-reload failed')
 for name,old,new,count in units:
  s=show(name)
  if s.get('ActiveState')!='active' or s.get('MainPID')!=state0[name].get('MainPID'):raise RuntimeError('Service changed state/PID: '+name)
  if s.get('WorkingDirectory')!=new and s.get('WorkingDirectory')!=new+'/current' and s.get('WorkingDirectory')!=new+'/backend':
   raise RuntimeError('Systemd new WorkingDirectory did not load: '+name)
  if old in s.get('ExecStart',''):raise RuntimeError('Old executable reference still active in loaded unit: '+name)
 if bots()!=pm0:raise RuntimeError('Telegram bot state/PIDs changed')
except Exception:
 for p,b in source.items():
  temp=p.with_name(p.name+'.canonical-recovery-tmp')
  with temp.open('wb') as f:f.write(b)
  mode,uid,gid=meta[p]
  os.chmod(temp,mode)
  os.chown(temp,uid,gid)
  os.replace(temp,p)
 cmd(['systemctl','daemon-reload'],30)
 print('UNIT_MIGRATION_ROLLBACK=APPLIED')
 raise
for name,old,new,count in units:
 print('UNIT_CANONICAL|'+name+'|'+show(name).get('WorkingDirectory')+'|PID='+str(state0[name]['MainPID']))
print('SYSTEMD_UNIT_FILES_UPDATED='+str(len(updated)))
print('SYSTEMD_DAEMON_RELOAD=PASS')
print('SYSTEMD_STATIC_VERIFY=PASS')
print('RUNNING_SERVICES_AND_TELEGRAM_BOTS=UNCHANGED')
print('NEXT_RESTART_USES_CANONICAL_PATHS=YES')
print('SERVICE_RESTARTS_PERFORMED=NO')
print('UNIT_CANONICAL_CUTOVER=PASS')
PY
